import { Request, Response } from "express";
import { dlqQueue, workflowQueue } from "../queues/workflowQueue";
import { prisma } from "../lib/prisma";

export async function replayDeadJob(req: Request, res: Response) {
  const { dlqJobId, modifiedPayload } = req.body;

  const dlqJob = await dlqQueue.getJob(dlqJobId);
  if (!dlqJob) return res.status(404).json({ error: "DLQ Job not found" });

  const payload = modifiedPayload || dlqJob.data.data;

  // Reset workflow step status in database
  await prisma.workflowStep.update({
    where: { id: payload.stepId },
    data: { status: "PENDING", errorMessage: null, attempts: 0 }
  });

  // Re-enqueue to active queue
  await workflowQueue.add("execute-step", payload);
  await dlqJob.remove();

  return res.status(200).json({ message: "Job successfully re-queued from DLQ" });
}
```

