### Step 2 · Authentication & RBAC Authorization Middleware
In `src/middleware/auth.ts`:
```typescript
import { Request, Response, NextFunction } from "express";
import { verifyAccessToken, TokenPayload } from "../utils/token";

export interface AuthenticatedRequest extends Request {
  user?: TokenPayload;
}

export function authenticate(req: AuthenticatedRequest, res: Response, next: NextFunction) {
  const authHeader = req.headers.authorization;
  if (!authHeader?.startsWith("Bearer ")) {
    return res.status(401).json({ error: "Access token missing or invalid format" });
  }

  const token = authHeader.split(" ")[1];
  try {
    req.user = verifyAccessToken(token);
    next();
  } catch (err) {
    return res.status(401).json({ error: "Expired or invalid access token" });
  }
}

export function authorize(roles: string[]) {
  return (req: AuthenticatedRequest, res: Response, next: NextFunction) => {
    if (!req.user) {
      return res.status(401).json({ error: "Unauthenticated" });
    }
    if (!roles.includes(req.user.role)) {
      return res.status(403).json({
        error: "Forbidden: You do not possess the required permissions for this resource"
      });
    }
    next();
  };
}
```

